INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7737317, 1275679, 28742, '<td valign="top">There he is! Seen better days and I predict he will see them again.</td>', 'There he is! Seen better days and I predict he will see them again.', '2023-01-27 00:27:05.000000', NULL, 1),
(7737320, 1275679, 91360, '<td valign="top">wish you fast recovery and great times in the future</td>', 'wish you fast recovery and great times in the future', '2023-01-27 00:36:56.000000', NULL, 1),
(7737325, 1275679, 67145, '<td valign="top">i personally see the body as a vehicle that we spend time in to experience this world .. some are given an easy ride .. some are not .. with everything in between .. <br/>but i''ve gotta say .. this photo brought tears to my eyes .. <br/>so bruised and beaten up .. hard to see and not feel so much compassion .. <br/>you are an absolute inspiration .. and i wish there were ppl like you in the world .. get well soon .. xx<br/>not voting yet ... :)</td>', 'i personally see the body as a vehicle that we spend time in to experience this world .. some are given an easy ride .. some are not .. with everything in between .. but i''ve gotta say .. this photo brought tears to my eyes .. so bruised and beaten up .. hard to see and not feel so much compassion .. you are an absolute inspiration .. and i wish there were ppl like you in the world .. get well soon .. xxnot voting yet ... :)', '2023-01-27 02:26:25.000000', NULL, 1),
(7737326, 1275647, 29535, '<td valign="top">Extra point for the pun.</td>', 'Extra point for the pun.', '2023-01-27 07:09:53.000000', NULL, 1),
(7737327, 1275679, 103142, '<td valign="top">Man!! Look at those bruises! They really beat you up! But what an awesome bear (and the Teddy bear is cute, too. :) <br/> <br/>Heal quickly, my friend!</td>', 'Man!! Look at those bruises! They really beat you up! But what an awesome bear (and the Teddy bear is cute, too. :)  Heal quickly, my friend!', '2023-01-27 10:23:30.000000', NULL, 1),
(7737329, 1275668, 30861, '<td valign="top">Cute is the right wors, as is "unbearably" LOL. I have a bear almost exactly like that one, BTW.</td>', 'Cute is the right wors, as is "unbearably" LOL. I have a bear almost exactly like that one, BTW.', '2023-01-27 12:17:42.000000', NULL, 1),
(7737330, 1275524, 30861, '<td valign="top">I had a dog that sang once. Unfortunately :-( Cool lighting.</td>', 'I had a dog that sang once. Unfortunately :-( Cool lighting.', '2023-01-27 12:18:19.000000', NULL, 1),
(7737331, 1275727, 30861, '<td valign="top">I love the dynamics of this shot. Someone tell that bear he can sit up straight now his spine is fixed :-)</td>', 'I love the dynamics of this shot. Someone tell that bear he can sit up straight now his spine is fixed :-)', '2023-01-27 12:19:04.000000', NULL, 1),
(7737332, 1275724, 30861, '<td valign="top">This actually brings a tear to my eye. So sweet. Beautifully exposed and processed.</td>', 'This actually brings a tear to my eye. So sweet. Beautifully exposed and processed.', '2023-01-27 12:19:52.000000', NULL, 1),
(7737333, 1275723, 30861, '<td valign="top">You figured out there''s some Irish in the Bear, eh? And, as an aside, like 75% of my nursing staff for the 12 days of purgatory were Irish. SO much fun, we had :-) I live the mood of this, my kind of slow, sad dirge...</td>', 'You figured out there''s some Irish in the Bear, eh? And, as an aside, like 75% of my nursing staff for the 12 days of purgatory were Irish. SO much fun, we had :-) I live the mood of this, my kind of slow, sad dirge...', '2023-01-27 12:22:19.000000', NULL, 1),
(7737334, 1275725, 30861, '<td valign="top">Someone STEPPED on that bear''s head! Although I guess not, polar bears have pointy heads :-) And I see by the 1994 he''s a Lillehammer bear, which I appreciate because I have been there long ago.</td>', 'Someone STEPPED on that bear''s head! Although I guess not, polar bears have pointy heads :-) And I see by the 1994 he''s a Lillehammer bear, which I appreciate because I have been there long ago.', '2023-01-27 12:24:34.000000', NULL, 1),
(7737335, 1275592, 30861, '<td valign="top">I''d know that Cal Bear anywhere, GeneralE :-) Thanks for being a good friend all these years :-)</td>', 'I''d know that Cal Bear anywhere, GeneralE :-) Thanks for being a good friend all these years :-)', '2023-01-27 12:26:17.000000', NULL, 1),
(7737336, 1275532, 30861, '<td valign="top">If she''s happy, I''m happy, BUT I prefer my bamboo stir-fried with sesame oil and some Cloud Ears, given the choice :-)</td>', 'If she''s happy, I''m happy, BUT I prefer my bamboo stir-fried with sesame oil and some Cloud Ears, given the choice :-)', '2023-01-27 12:27:34.000000', NULL, 1),
(7737338, 1275726, 30861, '<td valign="top">Is that bear BLUSHING???? Lovely setup :-) xoxo just for the heck of it (waves goodbye).</td>', 'Is that bear BLUSHING???? Lovely setup :-) xoxo just for the heck of it (waves goodbye).', '2023-01-27 12:28:43.000000', NULL, 1),
(7737339, 1275680, 30861, '<td valign="top">All the wannabe bears working on their music :-) This is lovely and I like it a lot.</td>', 'All the wannabe bears working on their music :-) This is lovely and I like it a lot.', '2023-01-27 12:32:41.000000', NULL, 1),
(7737340, 1275633, 30861, '<td valign="top">That''s a whole LOT of bear, that is! Myself, I''m a Kodiak but I embrace my variegated brethren and sistren wholeheartedly :-)</td>', 'That''s a whole LOT of bear, that is! Myself, I''m a Kodiak but I embrace my variegated brethren and sistren wholeheartedly :-)', '2023-01-27 12:34:12.000000', NULL, 1),
(7737341, 1275645, 30861, '<td valign="top">THAT bear''s livin'' the good life, innit he? Love the couch fabric. But you might want to give him a heads-up that the earphones need to be ON the ears, not the cheeks :-) Still, he''s a little bear yet and he can learn.</td>', 'THAT bear''s livin'' the good life, innit he? Love the couch fabric. But you might want to give him a heads-up that the earphones need to be ON the ears, not the cheeks :-) Still, he''s a little bear yet and he can learn.', '2023-01-27 12:36:10.000000', NULL, 1),
(7737342, 1275565, 30861, '<td valign="top">One thing I love here is the incongruity of the Adidas shows under the traditional Serape and the old-school pipes... This is a very engaging image.</td>', 'One thing I love here is the incongruity of the Adidas shows under the traditional Serape and the old-school pipes... This is a very engaging image.', '2023-01-27 12:37:59.000000', NULL, 1),
(7737343, 1275669, 30861, '<td valign="top">Hah! Melethia visiting me on Cape Cod circa 2005, 2006? You were close to the first DPCer to come to the Cape, if not the very first. I cost you a lot of money, didn''t I, what with tripods and ultra-wides and lawd knows what else. And here we are, all those years later :-)</td>', 'Hah! Melethia visiting me on Cape Cod circa 2005, 2006? You were close to the first DPCer to come to the Cape, if not the very first. I cost you a lot of money, didn''t I, what with tripods and ultra-wides and lawd knows what else. And here we are, all those years later :-)', '2023-01-27 12:43:30.000000', NULL, 1),
(7737344, 1275647, 30861, '<td valign="top">What a happy face! What a great title! I''ll pretend I don''t see the lion''s head where a bear belongs :-)</td>', 'What a happy face! What a great title! I''ll pretend I don''t see the lion''s head where a bear belongs :-)', '2023-01-27 12:45:30.000000', NULL, 1),
(7737345, 1275717, 30861, '<td valign="top">I like the Sam Isaac one :-)I''m also a Grateful Dead Dancing Bear (I''m an OG Deadhead and actually met Jerry Garcia way back in the beginning)</td>', 'I like the Sam Isaac one :-)I''m also a Grateful Dead Dancing Bear (I''m an OG Deadhead and actually met Jerry Garcia way back in the beginning)', '2023-01-27 12:48:05.000000', NULL, 1),
